export const brightEyeVertex="attribute vec3 a_position;\r\nattribute vec2 a_mask_texcoord;\r\n\r\nvarying vec2 v_texcoordOut;\r\nvarying vec2 v_mask_texcoordOut;\r\n\r\nuniform mat4 u_mvpMatrix;\r\n\r\nvoid main()\r\n{\r\n\tv_mask_texcoordOut = a_mask_texcoord;\r\n\tgl_Position = u_mvpMatrix * vec4(a_position,1.0);\r\n\tv_texcoordOut = (gl_Position.rg + 1.0) * 0.5;\r\n}";
export const brightEyeFragment="#ifdef GL_ES//for discriminate GLES & GL\r\n#ifdef GL_FRAGMENT_PRECISION_HIGH\r\nprecision highp float;\r\n#else\r\nprecision mediump float;\r\n#endif\r\n#else\r\n#define highp\r\n#define mediump\r\n#endif\r\n\r\nuniform sampler2D s_src_texture;\r\nuniform sampler2D s_mask_texture;\r\nuniform sampler2D s_white_area_lut_texture;\r\nuniform sampler2D s_pupil_mask_texture;\r\nuniform sampler2D s_pupil_highlight_mask_texture;\r\nuniform sampler2D s_pupil_other_lut_texture;\r\nuniform sampler2D s_pupil_highlight_lut_texture;\r\nuniform sampler2D s_pupil_sat_lut_texture;\r\n\r\n#ifdef HIGHLIGHT_SCREEN\r\nuniform sampler2D s_pupil_highlight_screen_texture;\r\n#endif\r\n\r\nvarying highp vec2 v_texcoordOut;\r\nvarying highp vec2 v_mask_texcoordOut;\r\n\r\nuniform highp float u_alpha;\r\nuniform highp float u_white_area_alpha;\r\nuniform highp float u_pupil_other_alpha;\r\nuniform highp float u_pupil_highlight_alpha;\r\nuniform highp float u_pupil_sat_alpha;\r\n\r\nuniform float u_pupil_other_sharp_alpha;\r\nuniform float u_sharp_threshold;\r\nuniform float u_sharp_factor;\r\nuniform float u_sharp_width_offset;\r\nuniform float u_sharp_height_offset;\r\n\r\nhighp vec3 Lut3D(highp vec3 textureColor, sampler2D s_LutTex)\r\n{\r\n    highp float blueColor = textureColor.b * 63.0;\r\n    highp vec2 quad1;\r\n    quad1.y = floor(floor(blueColor) / 8.0);\r\n    quad1.x = floor(blueColor) - (quad1.y * 8.0);\r\n    highp vec2 quad2;\r\n    quad2.y = floor(ceil(blueColor) / 8.0);\r\n    quad2.x = ceil(blueColor) - (quad2.y * 8.0);\r\n    highp vec2 texPos1;\r\n    texPos1.x = (quad1.x * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.r);\r\n    texPos1.y = (quad1.y * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.g);\r\n    highp vec2 texPos2;\r\n    texPos2.x = (quad2.x * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.r);\r\n    texPos2.y = (quad2.y * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.g);\r\n    highp vec3 newColor1 = clamp(texture2D(s_LutTex, texPos1).rgb,0.0,1.0);\r\n    highp vec3 newColor2 = clamp(texture2D(s_LutTex, texPos2).rgb,0.0,1.0);\r\n    highp vec3 newColor = clamp(mix(newColor1, newColor2, fract(blueColor)),0.0,1.0);\r\n    return newColor;\r\n}\r\n\r\nvoid main()\r\n{\r\n    highp vec4 src_color_alpha = texture2D(s_src_texture, v_texcoordOut);\r\n    highp vec3 src_color = src_color_alpha.rgb;\r\n    highp vec3 res_color = src_color;\r\n    highp vec3 mask_color = texture2D(s_mask_texture, v_mask_texcoordOut).rgb;\r\n    if (mask_color.r > 0.0500)\r\n    {\r\n        highp vec3 pupil_mask_color = texture2D(s_pupil_mask_texture, v_mask_texcoordOut).rgb;\r\n//        float gray = dot(src_color.rgb, vec3(0.298912, 0.586611, 0.114478));\r\n        vec3 white_area_res_color = src_color.rgb;\r\n        if (u_white_area_alpha > 0.0)\r\n        {\r\n            highp vec3 eye_lut_color = src_color.rgb;\r\n            eye_lut_color.r = texture2D(s_white_area_lut_texture, vec2(src_color.r, 0.5)).r;\r\n            eye_lut_color.g = texture2D(s_white_area_lut_texture, vec2(src_color.g, 0.5)).g;\r\n            eye_lut_color.b = texture2D(s_white_area_lut_texture, vec2(src_color.b, 0.5)).b;\r\n\r\n            white_area_res_color = mix(src_color, eye_lut_color, u_white_area_alpha);\r\n        }\r\n\r\n        vec3 pupil_res_color = src_color;\r\n        if (pupil_mask_color.r > 0.0 && (u_pupil_other_alpha > 0.0 || u_pupil_highlight_alpha > 0.0))\r\n        {\r\n            vec3 pupil_other_color = src_color;\r\n            vec3 pupil_highlight_color = src_color;\r\n            if (u_pupil_other_alpha > 0.0)\r\n            {\r\n                pupil_other_color.r = texture2D(s_pupil_other_lut_texture, vec2(src_color.r, 0.5)).r;\r\n                pupil_other_color.g = texture2D(s_pupil_other_lut_texture, vec2(src_color.g, 0.5)).g;\r\n                pupil_other_color.b = texture2D(s_pupil_other_lut_texture, vec2(src_color.b, 0.5)).b;\r\n\r\n                if (u_pupil_other_sharp_alpha > 0.0)\r\n                {\r\n                    vec3 blur_color = 0.25 * src_color;\r\n                    blur_color += 0.1250 * texture2D(s_src_texture, v_texcoordOut + vec2(-u_sharp_width_offset, 0.0)).rgb;\r\n                    blur_color += 0.1250 * texture2D(s_src_texture, v_texcoordOut + vec2(u_sharp_width_offset, 0.0)).rgb;\r\n                    blur_color += 0.1250 * texture2D(s_src_texture, v_texcoordOut + vec2(0.0, -u_sharp_height_offset)).rgb;\r\n                    blur_color += 0.1250 * texture2D(s_src_texture, v_texcoordOut + vec2(0.0, u_sharp_height_offset)).rgb;\r\n                    blur_color += 0.0625 * texture2D(s_src_texture, v_texcoordOut + vec2(u_sharp_width_offset, u_sharp_height_offset)).rgb;\r\n                    blur_color += 0.0625 * texture2D(s_src_texture, v_texcoordOut + vec2(-u_sharp_width_offset, -u_sharp_height_offset)).rgb;\r\n                    blur_color += 0.0625 * texture2D(s_src_texture, v_texcoordOut + vec2(-u_sharp_width_offset, u_sharp_height_offset)).rgb;\r\n                    blur_color += 0.0625 * texture2D(s_src_texture, v_texcoordOut + vec2(u_sharp_width_offset, -u_sharp_height_offset)).rgb;\r\n\r\n                    vec3 diff_color = (src_color - blur_color.rgb);\r\n                    vec3 neg_diff = max((-diff_color - u_sharp_threshold), 0.0);\r\n                    vec3 pos_diff = max((diff_color - u_sharp_threshold), 0.0);\r\n                    diff_color = pos_diff - neg_diff;\r\n\r\n                    vec3 sharpness_color = clamp(pupil_other_color.rgb + u_sharp_factor * diff_color, 0.0, 1.0);\r\n                    pupil_other_color = mix(pupil_other_color.rgb, sharpness_color.rgb, u_pupil_other_sharp_alpha);\r\n                }\r\n\r\n                pupil_other_color = mix(src_color, pupil_other_color, u_pupil_other_alpha);\r\n            }\r\n\r\n            float pupil_highlight_mask_val = texture2D(s_pupil_highlight_mask_texture, v_mask_texcoordOut).r;\r\n#ifdef HIGHLIGHT_SCREEN\r\n            float pupil_highlight_screen_val = texture2D(s_pupil_highlight_screen_texture, v_mask_texcoordOut).r;\r\n            pupil_highlight_mask_val *= pupil_highlight_screen_val;\r\n#else\r\n            if (pupil_mask_color.r < 0.5)\r\n            {\r\n                pupil_highlight_mask_val = 0.0;\r\n            }\r\n#endif\r\n            if (pupil_highlight_mask_val > 0.0 && u_pupil_highlight_alpha > 0.0)\r\n            {\r\n                pupil_highlight_color.r = texture2D(s_pupil_highlight_lut_texture, vec2(src_color.r, 0.5)).r;\r\n                pupil_highlight_color.g = texture2D(s_pupil_highlight_lut_texture, vec2(src_color.g, 0.5)).g;\r\n                pupil_highlight_color.b = texture2D(s_pupil_highlight_lut_texture, vec2(src_color.b, 0.5)).b;\r\n\r\n                pupil_highlight_color = mix(src_color, pupil_highlight_color, u_pupil_highlight_alpha);\r\n                pupil_highlight_color = clamp(pupil_highlight_color, 0.0, 1.0);\r\n            }\r\n            pupil_res_color = mix(pupil_other_color, pupil_highlight_color, pupil_highlight_mask_val);\r\n\r\n            if (u_pupil_sat_alpha > 0.0)\r\n            {\r\n                vec3 lut_color = Lut3D(pupil_res_color.rgb, s_pupil_sat_lut_texture);\r\n                pupil_res_color = mix(pupil_res_color.rgb, lut_color.rgb, u_pupil_sat_alpha);\r\n            }\r\n        }\r\n        res_color = mix(white_area_res_color, pupil_res_color, pupil_mask_color.r);\r\n        res_color = mix(src_color, res_color, u_alpha * mask_color.g);\r\n    }\r\n    gl_FragColor = vec4(res_color, src_color_alpha.a);\r\n}\r\n";
